function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  const seen = new Array(nums.length).fill(false);
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 0 || v >= nums.length) return 'Each value must be between 0 and nums.length - 1.';
    if (seen[v]) return 'All values of nums must be distinct.';
    seen[v] = true;
  }
  return null;
}

