function arrayNesting(nums) {
  let longest = 0;

  for (let start = 0; start < nums.length; start++) {
    let length = 0;
    let current = start;
    while (nums[current] !== -1) {
      const next = nums[current];
      nums[current] = -1;
      current = next;
      length++;
    }
    longest = Math.max(longest, length);
  }
  return longest;
}

