function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 10);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const nums = new Array(n);
  const mode = rand();
  if (mode < 0.15) {
    // Identity: every chain has length 1.
    for (let i = 0; i < n; i++) nums[i] = i;
  } else if (mode < 0.3) {
    // One big cycle through the shuffled order.
    for (let i = 0; i < n; i++) nums[order[i]] = order[(i + 1) % n];
  } else {
    // A random permutation with a random mix of cycles.
    for (let i = 0; i < n; i++) nums[i] = order[i];
  }
  return [nums];
}
